export type ParsedCpiSlashStakeInstruction<
  TProgram extends string = typeof PACTUM_TREASURY_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    cpiAuthority: TAccountMetas[0];
    config: TAccountMetas[1];
    globalConfig: TAccountMetas[2];
    marketplace: TAccountMetas[3];
    judge?: TAccountMetas[4] | undefined;
    arbiterProfile?: TAccountMetas[5] | undefined;
    stakeVault: TAccountMetas[6];
    recipientTokenAccount: TAccountMetas[7];
    usdcMint: TAccountMetas[8];
    treasuryCpiAuthority: TAccountMetas[9];
    coreProgram: TAccountMetas[10];
    tokenProgram: TAccountMetas[11];
  };
  data: CpiSlashStakeInstructionData;
};

export function parseCpiSlashStakeInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedCpiSlashStakeInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 12) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 12,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === PACTUM_TREASURY_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      cpiAuthority: getNextAccount(),
      config: getNextAccount(),
      globalConfig: getNextAccount(),
      marketplace: getNextAccount(),
      judge: getNextOptionalAccount(),
      arbiterProfile: getNextOptionalAccount(),
      stakeVault: getNextAccount(),
      recipientTokenAccount: getNextAccount(),
      usdcMint: getNextAccount(),
      treasuryCpiAuthority: getNextAccount(),
      coreProgram: getNextAccount(),
      tokenProgram: getNextAccount(),
    },
    data: getCpiSlashStakeInstructionDataDecoder().decode(instruction.data),
  };
}
